# PTX source for fp16 matrix multiplication (A[M,K] * B[K,N] = C[M,N])
PTX_SOURCE = r'''
.version 7.0
.target sm_80
.address_size 64

.visible .entry matmul_fp16(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 K,
    .param .u32 N
)
{
    // Thread indices
    .reg .u32  %tid_x, %tid_y;
    .reg .u32  %blk_x, %blk_y;
    .reg .u32  %row, %col;
    .reg .u32  %k;

    // Predicates
    .reg .pred %p0, %p1, %p2, %p3, %p4;

    // 64‑bit pointers
    .reg .u64  %A, %B, %C;
    .reg .u64  %addr_a, %addr_b, %addr_c;
    .reg .u64  %tmp0, %tmp1, %tmp2, %tmp3;

    // Scalars
    .reg .u32  %M, %K, %N;

    // FP16 registers
    .reg .f16 %a_val, %b_val, %c_val;

    // FP32 registers (accumulator and temporaries)
    .reg .f32 %acc, %a_f32, %b_f32;

    // Load kernel parameters
    ld.param.u64 %A, [A_ptr];
    ld.param.u64 %B, [B_ptr];
    ld.param.u64 %C, [C_ptr];
    ld.param.u32 %M, [M];
    ld.param.u32 %K, [K];
    ld.param.u32 %N, [N];

    // Get thread/block ids
    mov.u32 %tid_x, %tid.x;
    mov.u32 %tid_y, %tid.y;
    mov.u32 %blk_x, %ctaid.x;
    mov.u32 %blk_y, %ctaid.y;

    // Compute global row and column indices (tile size = 16)
    mad.lo.u32 %col, %blk_x, 16, %tid_x;   // col = blk_x*16 + tid_x
    mad.lo.u32 %row, %blk_y, 16, %tid_y;   // row = blk_y*16 + tid_y

    // Bounds check for output element
    setp.ge.u32 %p0, %row, %M;
    setp.ge.u32 %p1, %col, %N;
    or.pred %p2, %p0, %p1;                 // %p2 == true if out‑of‑bounds
    @%p2 bra DONE;                         // skip computation for OOB threads

    // Initialise accumulator
    mov.f32 %acc, 0f00000000;              // 0.0f in hex

    // Loop over K dimension
    mov.u32 %k, 0;
K_LOOP:
    setp.lt.u32 %p3, %k, %K;
    @!%p3 bra K_DONE;

    // ----- Load A[row, k] -----
    // addr = A + ((row * K) + k) * 2
    cvt.u64.u32 %tmp0, %row;
    cvt.u64.u32 %tmp1, %K;
    mul.lo.u64 %tmp2, %tmp0, %tmp1;            // row*K
    cvt.u64.u32 %tmp3, %k;
    add.u64 %tmp2, %tmp2, %tmp3;               // row*K + k
    mul.lo.u64 %tmp2, %tmp2, 2;                // *sizeof(fp16)
    add.u64 %addr_a, %A, %tmp2;
    ld.global.f16 %a_val, [%addr_a];

    // ----- Load B[k, col] -----
    // addr = B + ((k * N) + col) * 2
    cvt.u64.u32 %tmp0, %k;
    cvt.u64.u32 %tmp1, %N;
    mul.lo.u64 %tmp2, %tmp0, %tmp1;            // k*N
    cvt.u64.u32 %tmp3, %col;
    add.u64 %tmp2, %tmp2, %tmp3;               // k*N + col
    mul.lo.u64 %tmp2, %tmp2, 2;
    add.u64 %addr_b, %B, %tmp2;
    ld.global.f16 %b_val, [%addr_b];

    // Convert to fp32 and accumulate
    cvt.f32.f16 %a_f32, %a_val;
    cvt.f32.f16 %b_f32, %b_val;
    fma.rn.f32 %acc, %a_f32, %b_f32, %acc;

    // Increment k
    add.u32 %k, %k, 1;
    bra K_LOOP;
K_DONE:

    // Convert accumulator to fp16 and store C[row, col]
    cvt.rn.f16.f32 %c_val, %acc;

    // addr = C + ((row * N) + col) * 2
    cvt.u64.u32 %tmp0, %row;
    cvt.u64.u32 %tmp1, %N;
    mul.lo.u64 %tmp2, %tmp0, %tmp1;            // row*N
    cvt.u64.u32 %tmp3, %col;
    add.u64 %tmp2, %tmp2, %tmp3;               // row*N + col
    mul.lo.u64 %tmp2, %tmp2, 2;
    add.u64 %addr_c, %C, %tmp2;
    st.global.f16 [%addr_c], %c_val;

DONE:
    ret;
