# Python wrapper that loads and launches the PTX kernel
# ----------------------------------------------------------------------
import torch

class ModelNew:
    def __init__(self):
        # Load the PTX module using the provided harness
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        Computes C = A @ B where A and B are fp16 tensors on CUDA.
        Shapes:
            A: (M, K)
            B: (K, N)
        Returns:
            C: (M, N) fp16 tensor on CUDA
        """
        assert A.is_cuda and B.is_cuda
        assert A.dtype == torch.float16 and B.dtype == torch.float16
        M, K = A.shape
        K2, N = B.shape
        assert K == K2, "Incompatible shapes for matmul"

        # Allocate output tensor
        C = torch.empty((M, N), dtype=torch.float16, device='cuda')

        # Kernel launch configuration
        TILE = 16
        grid_x = (N + TILE - 1) // TILE
        grid_y = (M + TILE - 1) // TILE
        grid = (grid_x, grid_y, 1)
        block = (TILE, TILE, 1)

        # Prepare arguments: pointers and dimensions
        args = [
            A.data_ptr(),
            B.data_ptr(),
            C.data_ptr(),
            int(M),
            int(K),
            int(N)
        ]

        # Launch the kernel via the harness
        ptx_launch(self.module, "matmul_fp16", grid, block, args)

        return C
